package com.graphorm.example.university.generated.client;

import com.graphorm.core.metadata.ModelRegistry;
import com.graphorm.jdbc.dialect.PostgreSqlDialect;
import com.graphorm.jdbc.dialect.SqlDialect;
import com.graphorm.jdbc.executor.JdbcExecutor;
import java.util.Objects;
import javax.sql.DataSource;

/**
 * Prisma-style strongly typed database client generated by GraphORM.
 */
public class GraphOrmClient {
    private final JdbcExecutor executor;

    private final ModelRegistry registry;

    private final SqlDialect dialect;

    public GraphOrmClient(JdbcExecutor executor, ModelRegistry registry, SqlDialect dialect) {
        this.executor = Objects.requireNonNull(executor, "executor must not be null");
        this.registry = Objects.requireNonNull(registry, "registry must not be null");
        this.dialect = Objects.requireNonNull(dialect, "dialect must not be null");
    }

    public static Builder builder() {
        return new Builder();
    }

    public static GraphOrmClient create(DataSource dataSource, ModelRegistry registry) {
        return builder().dataSource(dataSource).registry(registry).build();
    }

    /**
     * Accessor for {@link Instructor} model operations.
     */
    public InstructorClient instructor() {
        return new InstructorClient(executor, registry, dialect);
    }

    /**
     * Accessor for {@link AuditLog} model operations.
     */
    public AuditLogClient auditLog() {
        return new AuditLogClient(executor, registry, dialect);
    }

    /**
     * Accessor for {@link GradeScale} model operations.
     */
    public GradeScaleClient gradeScale() {
        return new GradeScaleClient(executor, registry, dialect);
    }

    /**
     * Accessor for {@link Student} model operations.
     */
    public StudentClient student() {
        return new StudentClient(executor, registry, dialect);
    }

    /**
     * Accessor for {@link Course} model operations.
     */
    public CourseClient course() {
        return new CourseClient(executor, registry, dialect);
    }

    /**
     * Accessor for {@link Department} model operations.
     */
    public DepartmentClient department() {
        return new DepartmentClient(executor, registry, dialect);
    }

    /**
     * Accessor for {@link Enrollment} model operations.
     */
    public EnrollmentClient enrollment() {
        return new EnrollmentClient(executor, registry, dialect);
    }

    /**
     * Read-only accessor for {@link AuditSummary} view operations.
     */
    public AuditSummaryClient auditSummary() {
        return new AuditSummaryClient(executor, registry, dialect);
    }

    /**
     * Read-only accessor for {@link DepartmentStats} view operations.
     */
    public DepartmentStatsClient departmentStats() {
        return new DepartmentStatsClient(executor, registry, dialect);
    }

    /**
     * Read-only accessor for {@link StudentDashboard} view operations.
     */
    public StudentDashboardClient studentDashboard() {
        return new StudentDashboardClient(executor, registry, dialect);
    }

    /**
     * Builder for creating {@link GraphOrmClient} instances.
     */
    public static final class Builder {
        private DataSource dataSource;

        private JdbcExecutor executor;

        private ModelRegistry registry;

        private SqlDialect dialect = new PostgreSqlDialect();

        public Builder dataSource(DataSource dataSource) {
            this.dataSource = dataSource; return this;
        }

        public Builder executor(JdbcExecutor executor) {
            this.executor = executor; return this;
        }

        public Builder registry(ModelRegistry registry) {
            this.registry = registry; return this;
        }

        public Builder dialect(SqlDialect dialect) {
            this.dialect = dialect; return this;
        }

        public GraphOrmClient build() {
            if (executor == null && dataSource != null) executor = new JdbcExecutor(dataSource, dialect);
            Objects.requireNonNull(executor, "Either executor or dataSource must be configured");
            Objects.requireNonNull(registry, "ModelRegistry must not be null");
            return new GraphOrmClient(executor, registry, dialect);
        }
    }
}
